import{_ as e,o,c as r,a2 as a}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"AgentPay 多租户隔离与越权渗透测试报告 (T3.5 Conformance Report)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/reports/tenant-isolation-test-report.md","filePath":"specs/reports/tenant-isolation-test-report.md","lastUpdated":1792399623000}'),n={name:"specs/reports/tenant-isolation-test-report.md"};function d(i,t,l,c,s,_){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="agentpay-多租户隔离与越权渗透测试报告-t3-5-conformance-report" tabindex="-1">AgentPay 多租户隔离与越权渗透测试报告 (T3.5 Conformance Report) <a class="header-anchor" href="#agentpay-多租户隔离与越权渗透测试报告-t3-5-conformance-report" aria-label="Permalink to &quot;AgentPay 多租户隔离与越权渗透测试报告 (T3.5 Conformance Report)&quot;">​</a></h1><blockquote><p><strong>报告版本</strong>：v1.0.0<br><strong>执行日期</strong>：2026-10-18<br><strong>测试状态</strong>：<strong>100% 通过 (PASSED)</strong><br><strong>执行环境</strong>：macOS (Darwin arm64), Python 3.12.7 (pytest 9.1.1), Go 1.24<br><strong>涉及核心规范</strong>：</p><ul><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/multitenant-data-model.md" target="_blank" rel="noreferrer"><code>specs/multitenant-data-model.md</code></a> (多租户实体模型与隔离规范)</li><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/threat-model-v1.md" target="_blank" rel="noreferrer"><code>specs/threat-model-v1.md</code></a> (T1.6 威胁模型与越权攻击面)</li><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/security-model.md" target="_blank" rel="noreferrer"><code>specs/security-model.md</code></a> (RBAC 角色权限与租户安全边界)</li></ul></blockquote><hr><h2 id="_1-概述与测试目标" tabindex="-1">1. 概述与测试目标 <a class="header-anchor" href="#_1-概述与测试目标" aria-label="Permalink to &quot;1. 概述与测试目标&quot;">​</a></h2><p>在 AgentPay 多租户架构中，各个租户可能代表相互竞争的企业或团队，各自托管极度敏感的 AI Agent 业务资产、私有 API Key、内部上游路由、财务安全策略以及平台虚拟钱包资金。</p><p><strong>任务 T3.5 完成租户隔离与越权测试</strong> 旨在实施系统性、渗透级的负面攻击测试，严格验证以下安全边界：</p><ol><li><strong>水平越权防御（BOPLA / IDOR - Broken Object Level Authorization）</strong>： <ul><li>攻击者拥有合法租户凭证（Tenant Beta），尝试通过已知或遍历猜测的对象 ID 直接读取、修改或删除受害者（Tenant Alpha）名下的项目、成员、Agent、API Key、网关路由、安全策略及钱包账本；</li></ul></li><li><strong>垂直越权防御（BFLA - Broken Function Level Authorization &amp; RBAC Escalation）</strong>： <ul><li>租户内部低权限角色（如 <code>viewer</code>、<code>operator</code>）尝试调用需要更高权限（如 <code>admin</code>、<code>owner</code>）的写操作与敏感管理接口；</li></ul></li><li><strong>查询与列表搜索隔离（Data Contamination Prevention）</strong>： <ul><li>验证全量列表（List）与过滤接口在缺省过滤条件、空查询或通配符查询时，绝对不会泄露任何其他租户的记录（零污染不变量）；</li></ul></li><li><strong>API 参数混淆与跨租户注入防御（Path vs Payload Mismatch）</strong>： <ul><li>攻击者在 REST API 路径中使用自己的 <code>tenant_id</code>，但在 JSON Body 或查询参数中注入受害者的 <code>project_id</code>、<code>agent_id</code> 或 <code>route_id</code>，验证系统是否能够识别跨租户所有权并拦截；</li></ul></li><li><strong>数据面网关路由与钱包资金物理隔离</strong>： <ul><li>验证 Go Gateway 在数据面请求路径上执行租户隔离路由匹配（<code>MatchRouteForTenant</code>），以及虚拟钱包冻结、扣款与账本平账在不同租户间的完全独立性。</li></ul></li></ol><hr><h2 id="_2-隔离与越权测试覆盖矩阵" tabindex="-1">2. 隔离与越权测试覆盖矩阵 <a class="header-anchor" href="#_2-隔离与越权测试覆盖矩阵" aria-label="Permalink to &quot;2. 隔离与越权测试覆盖矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>测试维度</th><th>攻击测试用例 / 测试文件</th><th>目标对象域</th><th>预期安全响应</th><th>测试结果</th><th>关键安全断言</th></tr></thead><tbody><tr><td><strong>水平越权 (IDOR 读取)</strong></td><td><code>test_tenant_isolation_penetration.py</code><br><code>test_cross_tenant_idor_direct_access_blocked</code></td><td>Project, Agent, ApiKey, Route, Policy</td><td>403 Forbidden / <code>ERR_CROSS_TENANT_VIOLATION</code></td><td><strong>PASS</strong></td><td>猜测/直接访问他租户实体 ID 均被即时拒绝</td></tr><tr><td><strong>水平越权 (IDOR 篡改/删除)</strong></td><td><code>test_tenant_isolation_penetration.py</code><br><code>test_cross_tenant_idor_direct_access_blocked</code></td><td>Project, Agent, ApiKey, Route, Policy</td><td>403 Forbidden / Mismatch Error</td><td><strong>PASS</strong></td><td>跨租户修改预算、撤销/轮换密钥、删路由策略均被阻断</td></tr><tr><td><strong>查询列表零泄露</strong></td><td><code>test_tenant_isolation_penetration.py</code><br><code>test_cross_tenant_listing_zero_contamination</code></td><td>All Domains (List APIs)</td><td>返回列表长度仅为自有资源，受害者资源数为 0</td><td><strong>PASS</strong></td><td>没有任何接口返回混合租户数据</td></tr><tr><td><strong>垂直越权 (RBAC 提权)</strong></td><td><code>test_tenant_isolation_penetration.py</code><br><code>test_vertical_rbac_privilege_escalation_blocked</code></td><td>Member RBAC Matrix</td><td>403 Forbidden / <code>ERR_PERMISSION_DENIED</code></td><td><strong>PASS</strong></td><td>Viewer 无法创建项目、密钥、路由、策略</td></tr><tr><td><strong>REST API 路径载荷混淆</strong></td><td><code>test_tenant_isolation_penetration.py</code><br><code>test_api_rest_idor_and_spoofing_matrix</code></td><td>REST API Endpoints</td><td>403 Forbidden</td><td><strong>PASS</strong></td><td>拦截 Path tenant 与 Body project/agent 不一致注入</td></tr><tr><td><strong>最后 Owner 保护守卫</strong></td><td><code>test_member_rbac.py</code></td><td>Tenant Member</td><td>400 Bad Request / CannotRemoveLastOwner</td><td><strong>PASS</strong></td><td>严禁删除、降级或禁用租户唯一活跃 Owner</td></tr><tr><td><strong>数据面网关路由隔离</strong></td><td><code>gateway-go/internal/rcu/rcu_test.go</code><br><code>TestRCUMultiTenantRouteIsolation</code></td><td>Go Gateway RCU Router</td><td><code>MatchRouteForTenant</code> 返回 false</td><td><strong>PASS</strong></td><td>Tenant Beta 绝对无法命中 Tenant Alpha 的路由</td></tr><tr><td><strong>虚拟钱包与金融账本隔离</strong></td><td><code>gateway-go/tests/wallet_isolation_test.go</code><br><code>TestMultiTenantWalletIsolation</code></td><td>Virtual Wallet &amp; Ledger</td><td>余额无干扰，账本互不可见，对账 100% 独立</td><td><strong>PASS</strong></td><td>Alpha 的冻结扣费完全不影响 Beta 的可用余额</td></tr></tbody></table><hr><h2 id="_3-详细测试场景与渗透验证" tabindex="-1">3. 详细测试场景与渗透验证 <a class="header-anchor" href="#_3-详细测试场景与渗透验证" aria-label="Permalink to &quot;3. 详细测试场景与渗透验证&quot;">​</a></h2><h3 id="_3-1-跨租户-idor-读取与篡改拦截" tabindex="-1">3.1 跨租户 IDOR 读取与篡改拦截 <a class="header-anchor" href="#_3-1-跨租户-idor-读取与篡改拦截" aria-label="Permalink to &quot;3.1 跨租户 IDOR 读取与篡改拦截&quot;">​</a></h3><p>在测试环境搭建完全独立的两个租户：<strong>受害者 Tenant Alpha (<code>ten_alpha</code>)</strong> 与 <strong>攻击者 Tenant Beta (<code>ten_beta</code>)</strong>。</p><ul><li><strong>用例 IDOR-01（跨租户读取项目）</strong>： <ul><li>攻击者以 <code>ten_beta</code> 身份请求 <code>get_project(&quot;prj_alpha&quot;, expected_tenant_id=&quot;ten_beta&quot;)</code>；</li><li><strong>判定结果</strong>：系统抛出 <code>ProjectTenantMismatchError</code>，REST API 返回 HTTP 403 <code>ERR_CROSS_TENANT_VIOLATION</code>。</li></ul></li><li><strong>用例 IDOR-02（跨租户篡改项目预算）</strong>： <ul><li>攻击者 <code>ten_beta</code> 的管理员尝试调用 <code>update_project(&quot;prj_alpha&quot;, budget_cap_base_units=0)</code> 清空受害者预算；</li><li><strong>判定结果</strong>：系统校验 <code>actor.tenant_id != project.tenant_id</code>，立即阻断并抛出 <code>ProjectTenantMismatchError</code>。</li></ul></li><li><strong>用例 IDOR-03（跨租户窥探 / 轮换 API Key）</strong>： <ul><li>攻击者 <code>ten_beta</code> 尝试调用 <code>get_api_key(&quot;apk_alpha&quot;)</code>、<code>revoke_api_key(&quot;apk_alpha&quot;)</code> 或 <code>rotate_api_key(&quot;apk_alpha&quot;)</code>；</li><li><strong>判定结果</strong>：系统抛出 <code>ApiKeyTenantMismatchError</code>，REST API 返回 HTTP 403 <code>ERR_API_KEY_TENANT_MISMATCH</code>，受害者的密钥完好无损，且明文密钥零泄露。</li></ul></li><li><strong>用例 IDOR-04（跨租户恶意下线 Agent）</strong>： <ul><li>攻击者 <code>ten_beta</code> 尝试调用 <code>update_agent(agent_id=&quot;agt_alpha&quot;, name=&quot;Hacked&quot;)</code>；</li><li><strong>判定结果</strong>：系统抛出 <code>AgentTenantMismatchError</code>，阻断篡改。</li></ul></li><li><strong>用例 IDOR-05（跨租户篡改路由与窃取上游流量）</strong>： <ul><li>攻击者 <code>ten_beta</code> 尝试更新受害者内部路由 <code>update_route(&quot;rou_alpha&quot;, price_base_units=0)</code> 或 <code>delete_route(&quot;rou_alpha&quot;)</code>；</li><li><strong>判定结果</strong>：系统抛出 <code>RouteTenantMismatchError</code>，HTTP 403，受害者路由配置与计费单价不被篡改。</li></ul></li><li><strong>用例 IDOR-06（跨租户破坏安全策略）</strong>： <ul><li>攻击者 <code>ten_beta</code> 尝试修改受害者的单笔限额 <code>update_policy(&quot;pol_alpha&quot;, max_amount_per_request=99999999)</code>；</li><li><strong>判定结果</strong>：系统抛出 <code>PolicyTenantMismatchError</code>，HTTP 403。</li></ul></li></ul><h3 id="_3-2-列表查询零泄露与命名空间独立" tabindex="-1">3.2 列表查询零泄露与命名空间独立 <a class="header-anchor" href="#_3-2-列表查询零泄露与命名空间独立" aria-label="Permalink to &quot;3.2 列表查询零泄露与命名空间独立&quot;">​</a></h3><ul><li><strong>用例 LIST-01（空条件列表查询）</strong>： <ul><li>调用 <code>list_projects(tenant_id=&quot;ten_beta&quot;)</code>、<code>list_agents(tenant_id=&quot;ten_beta&quot;)</code>、<code>list_api_keys(tenant_id=&quot;ten_beta&quot;)</code>、<code>list_routes(tenant_id=&quot;ten_beta&quot;)</code>、<code>list_policies(tenant_id=&quot;ten_beta&quot;)</code>；</li><li><strong>判定结果</strong>：返回的数组中仅且仅包含 Tenant Beta 自行创建的资源；Tenant Alpha 的对应 ID 出现次数严格为 0。</li></ul></li><li><strong>用例 NAMESPACE-01（同名路径独立互不冲突）</strong>： <ul><li>Tenant Alpha 在名下创建了 <code>/api/v1/secret-model</code> 路由；</li><li>Tenant Beta 随后在其名下也创建了相同的 <code>/api/v1/secret-model</code> 路由（指向 Beta 的独立上游）；</li><li><strong>判定结果</strong>：数据库通过 <code>uq_tenant_route_path UNIQUE (tenant_id, path_pattern)</code> 保证两份路由独立共存、互不冲突、映射到各自租户上游。</li></ul></li></ul><h3 id="_3-3-垂直-rbac-越权拦截" tabindex="-1">3.3 垂直 RBAC 越权拦截 <a class="header-anchor" href="#_3-3-垂直-rbac-越权拦截" aria-label="Permalink to &quot;3.3 垂直 RBAC 越权拦截&quot;">​</a></h3><p>在租户 <code>ten_alpha</code> 内部配置了具有 <code>viewer</code> 角色的只读成员 <code>usr_viewer</code>：</p><ul><li><strong>用例 RBAC-01</strong>：<code>usr_viewer</code> 尝试创建 Project $\\rightarrow$ 抛出 <code>PermissionDeniedError</code> (<code>required_permission=&quot;project:create&quot;</code>)；</li><li><strong>用例 RBAC-02</strong>：<code>usr_viewer</code> 尝试创建 API Key $\\rightarrow$ 抛出 <code>PermissionDeniedError</code> (<code>required_permission=&quot;apikey:create&quot;</code>)；</li><li><strong>用例 RBAC-03</strong>：<code>usr_viewer</code> 尝试创建网关 Route $\\rightarrow$ 抛出 <code>PermissionDeniedError</code> (<code>required_permission=&quot;policy:write&quot;</code>)；</li><li><strong>用例 RBAC-04</strong>：<code>usr_viewer</code> 尝试创建财务 Policy $\\rightarrow$ 抛出 <code>PermissionDeniedError</code> (<code>required_permission=&quot;policy:write&quot;</code>)。</li></ul><h3 id="_3-4-api-路径与载荷混淆注入-parameter-tampering" tabindex="-1">3.4 API 路径与载荷混淆注入（Parameter Tampering） <a class="header-anchor" href="#_3-4-api-路径与载荷混淆注入-parameter-tampering" aria-label="Permalink to &quot;3.4 API 路径与载荷混淆注入（Parameter Tampering）&quot;">​</a></h3><p>通过 ASGI HTTP Client 模拟黑客发送特制篡改报文：</p><ul><li><strong>用例 INJECT-01（伪造绑定）</strong>： <ul><li>请求：<code>POST /api/v1/tenants/ten_beta/agents</code></li><li>Body：<code>{&quot;project_id&quot;: &quot;prj_alpha&quot;, &quot;name&quot;: &quot;Trojan Agent&quot;}</code></li><li><strong>判定结果</strong>：服务层在创建 Agent 前校验 <code>project.tenant_id == ten_beta</code>，发现 <code>prj_alpha</code> 属于 <code>ten_alpha</code>，拦截并返回 HTTP 403 <code>ERR_CROSS_TENANT_VIOLATION</code>。</li></ul></li></ul><h3 id="_3-5-虚拟钱包与账本跨租户隔离-go-gateway" tabindex="-1">3.5 虚拟钱包与账本跨租户隔离 (Go Gateway) <a class="header-anchor" href="#_3-5-虚拟钱包与账本跨租户隔离-go-gateway" aria-label="Permalink to &quot;3.5 虚拟钱包与账本跨租户隔离 (Go Gateway)&quot;">​</a></h3><p>在 Go Gateway 数据面建立 <code>wal_alpha_001</code>（可用余额 50 USDC）与 <code>wal_beta_002</code>（可用余额 10 USDC）：</p><ul><li><strong>用例 WALLET-01（资金操作绝对无交叉）</strong>： <ul><li>对 Tenant Alpha 发起 5 USDC 的预冻结与确认实扣（Hold &amp; Capture）；</li><li><strong>判定结果</strong>： <ul><li>Tenant Alpha 余额变动为：Available 45 USDC，Held 0 USDC；</li><li>Tenant Beta 余额变动为：Available 10 USDC，Held 0 USDC（<strong>100% 未受任何影响</strong>）。</li></ul></li></ul></li><li><strong>用例 WALLET-02（账本流水物理隔离）</strong>： <ul><li>查询 Tenant Beta 关联的账本流水记录 <code>GetLedgerEntries(ctx, &quot;wal_beta_002&quot;)</code>；</li><li><strong>判定结果</strong>：返回记录数为 0，完全看不到 Tenant Alpha 的扣款审计记录。</li></ul></li><li><strong>用例 WALLET-03（双轨对账独立平账）</strong>： <ul><li>分别对两边执行 <code>ReconcileBalance</code>，各自依据自身的只追加账本流水重新计算缓存，两边均为 <code>IsBalanced == true</code>。</li></ul></li></ul><hr><h2 id="_4-结论与审计合规证明" tabindex="-1">4. 结论与审计合规证明 <a class="header-anchor" href="#_4-结论与审计合规证明" aria-label="Permalink to &quot;4. 结论与审计合规证明&quot;">​</a></h2><p>通过上述渗透测试套件（<code>test_tenant_isolation_penetration.py</code>、<code>test_route_policy_lifecycle.py</code>、<code>test_member_rbac.py</code> 与 <code>wallet_isolation_test.go</code>），全仓共计执行并通过了 <strong>285+ 项自动化测试</strong>。</p><p><strong>测试结论</strong>：</p><ol><li><strong>多租户隔离完备性</strong>：AgentPay 在控制面（Python）与数据面（Go Gateway）均落地了不可逾越的租户所有权强校验；</li><li><strong>越权防御有效性</strong>：所有已知的 IDOR、BOPLA、BFLA、参数混淆与跨租户注入攻击向量均被 100% 拦截并返回规范的 403 / 404 错误响应；</li><li><strong>金融账本安全性</strong>：虚拟钱包账户、冻结记录与只追加记账流水具备完全独立的数据隔离边界。</li></ol><p><strong>T3.5 验收标准全部满足，本任务正式闭环签署。</strong></p>',32)])])}const p=e(n,[["render",d]]);export{u as __pageData,p as default};
